using FleetManagement.Core;
var now=new DateTime(2026,11,26,10,0,0);
var fleet=FleetRules.Sample(now);
void Check(bool result,string name){if(!result)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
Trip Candidate(int vehicle,int driver,DateTime start,DateTime end)=>new(999,vehicle,driver,"A","B",start,end,20,-1);
Check(FleetRules.ValidateTrip(fleet,Candidate(1,3,now,now.AddMinutes(5)))?.Contains("Vehicle")==true,"vehicle overlap");
Check(FleetRules.ValidateTrip(fleet,Candidate(4,1,now,now.AddMinutes(5)))?.Contains("Driver")==true,"driver overlap");
Check(FleetRules.ValidateTrip(fleet,Candidate(1,1,now.AddMinutes(60),now.AddMinutes(90)))==null,"adjacent intervals");
Check(FleetRules.ValidateTrip(fleet,Candidate(4,4,now,now))!=null,"invalid interval");
Check(FleetRules.ValidateTrip(fleet,Candidate(999,4,now,now.AddHours(1)))!=null,"unknown vehicle");
Check(FleetRules.ValidateTrip(fleet,Candidate(4,4,now,now.AddHours(1)) with{Distance=0})!=null,"zero distance");
Check(FleetRules.Recommend(fleet,now,now.AddMinutes(20),now)?.VehicleId==4,"recommendation skips busy and overdue vehicles");
Check(FleetRules.Recommend(fleet,now,now,now)==null,"invalid recommendation interval");
Check(FleetRules.Assess(fleet.Vehicles[0],now).Status=="Healthy","healthy service");
Check(FleetRules.Assess(fleet.Vehicles[1],now).Status=="Soon","service approaching");
Check(FleetRules.Assess(fleet.Vehicles[2],now).Status=="Due","service overdue");
Check(FleetRules.Progress(fleet.Trips[0],now)==0.4,"simulation progress");
Check(FleetRules.TripStatus(fleet.Trips[0],fleet.Trips[0].End)=="Completed","completed boundary");
var newVehicle=fleet.Vehicles[0] with{Id=5,Plate="NEW-005"};
Check(FleetRules.ValidateVehicle(fleet,newVehicle,now)==null,"valid vehicle");
Check(FleetRules.ValidateVehicle(fleet,newVehicle with{Plate=" fm-102 "},now)!=null,"duplicate registration");
Check(FleetRules.ValidateVehicle(fleet,newVehicle with{Mileage=-1},now)!=null,"negative mileage");
Check(FleetRules.ValidateVehicle(fleet,newVehicle with{LastServiceMileage=newVehicle.Mileage+1},now)!=null,"service mileage above odometer");
Check(FleetRules.ValidateVehicle(fleet,newVehicle with{ServiceIntervalDays=0},now)!=null,"invalid service interval");
Check(FleetRules.ValidateVehicle(fleet,newVehicle with{LastService=now.AddDays(1)},now)!=null,"future service date");
Check(FleetRules.ValidateDriver(fleet,new Driver(5,"New driver","NEW-005",4))==null,"valid driver");
Check(FleetRules.ValidateDriver(fleet,new Driver(5,"New driver"," demo-101 ",4))!=null,"duplicate license");
Check(FleetRules.ValidateDriver(fleet,new Driver(5,"New driver","NEW-005",-1))!=null,"invalid experience");
Check(FleetRules.CanRemoveVehicle(fleet,1)!=null,"protect vehicle history");
Check(FleetRules.CanRemoveVehicle(fleet,3)==null,"remove unassigned vehicle");
Check(FleetRules.CanRemoveDriver(fleet,1)!=null,"protect driver history");
Check(FleetRules.CanRemoveDriver(fleet,999)!=null,"unknown driver");
Check(FleetRules.CanChangeTrip(fleet,103,now)==null,"scheduled trip editable");
Check(FleetRules.CanChangeTrip(fleet,101,now)!=null,"active trip protected");
Check(FleetRules.CanChangeTrip(fleet,104,now)!=null,"completed trip protected");
Check(FleetRules.CanChangeTrip(fleet,999,now)!=null,"unknown trip protected");
Check(FleetRules.ValidateTrip(fleet,fleet.Trips.Single(t=>t.Id==103))==null,"editing ignores own assignment");
Check(FleetRules.Recommend(fleet,now.AddHours(3),now.AddHours(5),now,103)?.VehicleId==4,"recommendation ignores own trip");
var report=FleetReport.Build(fleet,now,now.Date,now.Date);
Check(report.Trips==4 && report.Completed==1 && report.Active==2 && report.Scheduled==1,"trip report status totals");
Check(report.CompletedDistanceKm==112 && report.PlannedDistanceKm==418,"report distance totals");
Check(report.ServiceDue==1 && report.ServiceSoon==1,"report maintenance counts");
Check(report.VehicleRows.Single(v=>v.Registration=="FM-102").CompletedDistanceKm==112,"vehicle report aggregation");
Check(FleetReport.Build(fleet,now,now.AddDays(2),now.AddDays(2)).Trips==0,"empty date filter");
Check(!FleetReport.ValidRange(now,now.AddDays(-1))&&!FleetReport.ValidRange(now,now.AddDays(366)),"reject invalid report ranges");
using(var stream=new MemoryStream(FleetReport.ExportXlsx(report,now,now)))
using(var zip=new System.IO.Compression.ZipArchive(stream)){
    Check(zip.GetEntry("xl/workbook.xml") is not null && zip.GetEntry("xl/worksheets/sheet2.xml") is not null,"xlsx package structure");
    using var reader=new StreamReader(zip.GetEntry("xl/worksheets/sheet1.xml")!.Open());
    Check(reader.ReadToEnd().Contains("<v>112</v>"),"xlsx numeric cell");
}
var malicious=report with{VehicleRows=[new("=1+1","A&B",0,0,0,"Healthy")]};
using(var stream=new MemoryStream(FleetReport.ExportXlsx(malicious,now,now)))
using(var zip=new System.IO.Compression.ZipArchive(stream))
using(var reader=new StreamReader(zip.GetEntry("xl/worksheets/sheet2.xml")!.Open())){
    var sheet=reader.ReadToEnd();
    Check(sheet.Contains("=1+1")&&sheet.Contains("inlineStr")&&!sheet.Contains("<f>")&&sheet.Contains("A&amp;B"),"xlsx text escaping and formula safety");
}
Check(FleetCalendar.WeekStart(now)==new DateTime(2026,11,23),"calendar Monday start");
Check(FleetCalendar.WeekStart(new DateTime(2026,11,29))==new DateTime(2026,11,23),"calendar Sunday boundary");
var events=FleetCalendar.Entries(fleet,now.Date,now.Date.AddDays(1));
Check(events.Count(e=>e.Kind=="Trip")==4,"calendar includes today's trips");
var service=FleetCalendar.Entries(fleet,now.Date.AddDays(19),now.Date.AddDays(22));
Check(service.Any(e=>e.Kind=="Service due"&&e.VehicleId==2&&e.TripId==null),"calendar service deadline");
Check(FleetCalendar.Entries(fleet,now.AddMinutes(60),now.AddMinutes(70)).All(e=>e.TripId!=101),"calendar excludes trip ending at interval start");
var overnight=FleetRules.Sample(now);overnight.Trips.Add(new(200,1,1,"A","B",now.Date.AddHours(23),now.Date.AddDays(1).AddHours(2),30,-1));
Check(FleetCalendar.Entries(overnight,now.Date.AddDays(1),now.Date.AddDays(2)).Any(e=>e.TripId==200),"calendar cross-midnight trip");
var points=RouteOptimizer.Generate(20,42);
var routes=RouteOptimizer.Compare(points);
Check(points.SequenceEqual(RouteOptimizer.Generate(20,42)),"route reproducible seed");
Check(routes.All(r=>r.Stops.Count==points.Count+1&&r.Stops[0]==points[0]&&r.Stops[^1]==points[0]),"route closed at depot");
Check(routes.All(r=>r.Stops.SkipLast(1).Select(s=>s.Id).Order().SequenceEqual(points.Select(s=>s.Id).Order())),"route visits same stops exactly once");
Check(routes[2].DistanceKm<=Math.Min(routes[0].DistanceKm,routes[1].DistanceKm)+1e-8,"2-opt never worsens seed tour");
Check(routes.Count==4&&routes[3].DistanceKm<=routes[2].DistanceKm+1e-8,"multi-start never worsens single-start");
for(int routeSeed=0;routeSeed<5;routeSeed++){
    var small=RouteOptimizer.Generate(9,routeSeed);var candidates=RouteOptimizer.Compare(small);
    Check(candidates.Count==5&&candidates[^1].DistanceKm<=candidates.Take(4).Min(r=>r.DistanceKm)+1e-8,"exact optimum bounds heuristics");
    Check(candidates.All(r=>r.Stops.SkipLast(1).Select(v=>v.Id).Order().SequenceEqual(small.Select(v=>v.Id).Order())),"all route strategies visit each stop once");
}
var square=RouteOptimizer.Compare([new(0,"Depot",0,0),new(1,"A",1,1),new(2,"B",0,1),new(3,"C",1,0)]);
Check(Math.Abs(square[^1].DistanceKm-4)<1e-8,"Held–Karp exact unit square");
Check(routes.All(r=>Math.Abs(r.DistanceKm-RouteOptimizer.Length(r.Stops))<1e-8),"route distance recomputation");
Check(Math.Abs(RouteOptimizer.Distance(new(1,"A",0,0),new(2,"B",3,4))-5)<1e-8,"Euclidean distance");
Check(RouteOptimizer.Compare([new(0,"Depot",0,0),new(1,"Stop",3,4)]).All(r=>r.DistanceKm==10),"two-stop round trip");
bool invalidRoute=false;try{RouteOptimizer.Compare([new(0,"Depot",0,0),new(0,"Duplicate",1,1)]);}catch(ArgumentException){invalidRoute=true;}
Check(invalidRoute,"route rejects duplicate ids");
var experiment=MaintenanceLearning.Train();
var repeat=MaintenanceLearning.Train();
Check(experiment.TrainRows==2400&&experiment.TestRows==720,"ML dataset dimensions");
Check(MaintenanceLearning.Generate(42,0,40,60).Select(x=>x.VehicleId).Distinct().Intersect(MaintenanceLearning.Generate(42^0x5A17,1000,12,60).Select(x=>x.VehicleId)).Count()==0,"ML held-out vehicle split");
Check(experiment.Test==repeat.Test,"ML deterministic training");
Check(experiment.LossHistory[^1]<experiment.LossHistory[0],"ML training reduces loss");
Check(experiment.Test.TP+experiment.Test.FP+experiment.Test.TN+experiment.Test.FN==experiment.TestRows,"ML confusion matrix totals");
Check(experiment.Test.Brier<experiment.Baseline.Brier,"ML improves held-out Brier versus prevalence baseline");
var normal=new TelemetryFeatures(80,1.5,13.8,.2,1000);
var stressed=new TelemetryFeatures(110,5.5,11.8,1.3,5500);
Check(experiment.Model.Predict(normal)<experiment.Model.Predict(stressed),"ML synthetic stress ranking");
Check(experiment.Model.Predict(stressed) is >=0 and <=1,"ML probability bounds");
Check(experiment.Model.Explain(stressed).Count==5,"ML feature contribution count");
Check(experiment.Test.F1 is >=0 and <=1&&experiment.Test.Recall is >=0 and <=1,"ML metric bounds");
Console.WriteLine($"ML held-out: F1={experiment.Test.F1:F3}; Brier={experiment.Test.Brier:F3}; baseline Brier={experiment.Baseline.Brier:F3}");
var eta=EtaLearning.Train();
Check(eta.TrainRows==1600&&eta.TestRows==400,"ETA dataset sizes");
Check(eta.Test.Mae<eta.Baseline.Mae,"ETA improves MAE over free-flow baseline");
Check(eta.Test.Rmse<eta.Baseline.Rmse,"ETA improves RMSE over free-flow baseline");
Check(eta.Test.R2>.8,"ETA synthetic fit");
Check(eta.ValidationResidual90>0,"ETA validation residual quantile");
var journey=new EtaFeatures(120,.1,70,3,.5);
Check(eta.Model.Predict(journey with{Traffic=.9})>eta.Model.Predict(journey),"ETA responds to traffic");
Check(eta.Model.Predict(journey with{Stops=10})>eta.Model.Predict(journey),"ETA responds to stops");
Check(EtaLearning.Train().Test==eta.Test,"ETA deterministic");
Check(!new EtaFeatures(0,.5,0,0,0).Valid,"ETA invalid input");
var anomaly=AnomalyLearning.Run();
Check(anomaly.TrainRows==500&&anomaly.Test.Count==240,"anomaly reference and test sizes");
Check(AnomalyLearning.Generate(42,500,false).All(x=>!x.InjectedAnomaly),"anomaly clean reference");
Check(anomaly.Metrics.TP+anomaly.Metrics.TN+anomaly.Metrics.FP+anomaly.Metrics.FN==240,"anomaly confusion totals");
Check(anomaly.Metrics.Recall>.7,"anomaly detects injected faults");
Check(anomaly.Test.SequenceEqual(AnomalyLearning.Run().Test),"anomaly reproducibility");
Check(AnomalyLearning.Run(42,5).Test.Count(t=>t.Flagged)<=AnomalyLearning.Run(42,3).Test.Count(t=>t.Flagged),"anomaly threshold monotonicity");
Console.WriteLine($"ETA synthetic MAE={eta.Test.Mae:F2}; baseline={eta.Baseline.Mae:F2}; anomaly recall={anomaly.Metrics.Recall:F3}");
var twinConfig=new TwinConfig(8,42,.4,1,"Overheat");
var twin=new DigitalTwin(twinConfig,experiment.Model,eta.Model);
var twinRepeat=new DigitalTwin(twinConfig,experiment.Model,eta.Model);
for(int i=0;i<3;i++){twin.Step();twinRepeat.Step();}
Check(twin.Minute==15&&twin.Vehicles.SequenceEqual(twinRepeat.Vehicles),"twin reproducible stepping");
Check(twin.Vehicles[0].Temperature>100&&twin.Vehicles[0].AnomalyScore>=3.5,"twin injected overheating");
Check(twin.Events.Any(e=>e.VehicleId==1&&e.Kind=="Anomaly"),"twin anomaly event");
Check(twin.Vehicles.All(v=>v.TravelledKm>=0&&v.TravelledKm<=v.DistanceKm&&v.FuelLitres>=0&&v.Risk is >=0 and <=1),"twin state bounds");
Check(twin.History(1).Count==4,"twin history includes initial state");
var broken=new DigitalTwin(twinConfig with{Incident="Breakdown"},experiment.Model,eta.Model);
for(int i=0;i<3;i++)broken.Step();
var stopped=broken.Vehicles[0].TravelledKm;broken.Step();
Check(broken.Vehicles[0].Status=="Breakdown"&&broken.Vehicles[0].TravelledKm==stopped&&broken.Vehicles[0].EtaMinutes==null,"twin breakdown stops movement");
var offline=new DigitalTwin(twinConfig with{Incident="Signal loss"},experiment.Model,eta.Model);
for(int i=0;i<3;i++)offline.Step();
Check(offline.Vehicles[0].Status=="Offline"&&offline.Vehicles[0].EtaMinutes==null,"twin offline ETA unavailable");
for(int i=0;i<6;i++)offline.Step();
Check(offline.Vehicles[0].Status=="En route","twin signal recovers");
for(int i=0;i<150;i++)twin.Step();
Check(twin.Finished&&twin.Minute<=DigitalTwin.MaxMinutes&&twin.History(1).Count<=145,"twin bounded simulation");
Check(!new TwinConfig(100,42,.4).Valid,"twin validates configuration");
var notices=FleetAdvisor.Assess(fleet,now);
Check(notices.Any(a=>a.Subject=="FM-310"&&a.Severity=="High"),"advisor detects overdue service");
Check(notices.Any(a=>a.Subject=="FM-205"&&a.Severity=="Medium"),"advisor detects approaching service");
Check(notices.All(a=>a.Evidence.Length>0&&a.Recommendation.Length>0),"advisor evidence and recommendations");
Check(notices.Select(a=>a.Key).Distinct().Count()==notices.Count,"advisor unique alert ids");
Check(FleetAdvisor.Answer(fleet,now,"ТО").Evidence.Count==2,"advisor Russian maintenance intent");
var russianAnswer=FleetAdvisor.Answer(fleet,now,"ТО",russian:true);
Check(russianAnswer.Title=="Проверка обслуживания"&&russianAnswer.Evidence.All(a=>a.Destination=="Maintenance")&&russianAnswer.Evidence.Any(a=>a.Title.Contains("ТО")),"localized advisor retains canonical destinations");
Check(FleetAdvisor.Assess(fleet,now,russian:true).Select(a=>a.Key).SequenceEqual(notices.Select(a=>a.Key)),"localized advisor preserves alert identity and order");
Check(FleetAdvisor.Answer(fleet,now,"unknown request").Title=="Supported questions","advisor unsupported intent");
Check(FleetAdvisor.Answer(fleet,now,"dispatch").Summary.Contains("FM-415"),"advisor dispatch availability");
var riskyFleet=FleetRules.Sample(now);riskyFleet.Trips.Add(new(300,3,3,"A","B",now.AddHours(6),now.AddHours(7),100,-1));
Check(FleetAdvisor.Assess(riskyFleet,now).Any(a=>a.Key=="dispatch:300"),"advisor flags upcoming service-due assignment");
Check(FleetAdvisor.AssessTwin(broken).Any(a=>a.Key=="twin:1:breakdown"),"advisor breakdown alert");
var offlineAlert=new DigitalTwin(twinConfig with{Incident="Signal loss"},experiment.Model,eta.Model);
for(int i=0;i<3;i++)offlineAlert.Step();
Check(FleetAdvisor.AssessTwin(offlineAlert).Any(a=>a.Key=="twin:1:offline")&&FleetAdvisor.AssessTwin(offlineAlert).All(a=>a.Key!="twin:1:risk"),"advisor suppresses stale model alerts");
Check(FleetAdvisor.Assess(new([],[],[]),now).Count==0,"advisor empty register");
var scenario=MultiVehicleDispatch.Generate(20,4,30,42);
var plans=MultiVehicleDispatch.Compare(scenario);
Check(plans.Count==3,"multi dispatch strategy count");
Check(plans.All(p=>p.Assigned+p.Unassigned.Count==scenario.Orders.Count),"multi dispatch order accounting");
Check(plans.All(p=>p.Tours.SelectMany(t=>t.Visits.Select(v=>v.Order.Id)).Concat(p.Unassigned.Select(o=>o.Id)).Order().SequenceEqual(scenario.Orders.Select(o=>o.Id).Order())),"multi dispatch exactly once or unassigned");
Check(plans.All(p=>p.Tours.All(t=>t.Load<=t.Vehicle.Capacity)),"multi dispatch capacity");
Check(plans.All(p=>p.Tours.All(t=>t.ReturnMinute<=scenario.ShiftMinutes+1e-8)),"multi dispatch depot return");
Check(plans.All(p=>p.Tours.SelectMany(t=>t.Visits).All(v=>v.Start>=v.Order.Earliest&&v.Start<=v.Order.Latest+1e-8&&v.End==v.Start+v.Order.ServiceMinutes)),"multi dispatch time windows");
Check(plans[2].Assigned>=plans[0].Assigned&&plans[2].Assigned>=plans[1].Assigned,"multi dispatch recommendation coverage");
Check(plans.Where(p=>p.Assigned==plans[2].Assigned).All(p=>plans[2].Distance<=p.Distance+1e-8),"multi dispatch recommendation distance");
Check(MultiVehicleDispatch.Compare(MultiVehicleDispatch.Generate(20,4,30,42))[2].Distance==plans[2].Distance,"multi dispatch deterministic");
var tiny=new DispatchScenario(new(0,"Depot",0,0),[new(1,new(1,"A",3,4),2,20,30,5)],[new(1,2)],60,60);
var tinyTour=MultiVehicleDispatch.Compare(tiny)[2].Tours[0];
Check(tinyTour.Visits[0].Arrival==5&&tinyTour.Visits[0].Start==20&&tinyTour.ReturnMinute==30&&tinyTour.Distance==10,"multi dispatch waiting and return");
Check(MultiVehicleDispatch.Compare(tiny with{Vehicles=[new(1,1)]})[2].Unassigned.Count==1,"multi dispatch impossible capacity");
Check(MultiVehicleDispatch.Compare(tiny with{Orders=[tiny.Orders[0] with{Latest=3,Earliest=0} ]})[2].Unassigned.Count==1,"multi dispatch impossible deadline");
Console.WriteLine($"Dispatch synthetic: baseline {plans[0].Assigned}/{plans[0].Distance:F1} km; insertion {plans[1].Assigned}/{plans[1].Distance:F1} km");
var comparisons=ScenarioComparison.Compare(8,42,.2,.8,experiment.Model,eta.Model);
Check(comparisons.Count==3,"what-if scenario count");
Check(comparisons.All(r=>r.Arrived+r.BrokenDown+r.Unfinished==r.Vehicles),"what-if fleet accounting");
Check(comparisons.All(r=>r.ElapsedMinutes<=DigitalTwin.MaxMinutes&&r.FuelLitres>=0&&r.DistanceKm>=0),"what-if bounded outcomes");
Check(comparisons[2].BrokenDown==1,"what-if injected breakdown");
Check(comparisons[0].FuelPer100Km is double a&&comparisons[1].FuelPer100Km is double b&&a<b,"what-if higher simulated fuel intensity");
Check(comparisons.SequenceEqual(ScenarioComparison.Compare(8,42,.2,.8,experiment.Model,eta.Model)),"what-if reproducibility");
var geoRoutes=GeoTracking.Sample();
Check(geoRoutes.Count==3&&geoRoutes.SelectMany(r=>r.Hubs).All(h=>h.Position.Valid),"geo valid sample coordinates");
Check(Math.Abs(GeoTracking.Distance(new(0,0),new(0,1))-111.195)<.01,"geo great-circle reference");
Check(GeoTracking.Distance(new(45,15),new(45,15))==0,"geo identical coordinates");
var geoRoute=geoRoutes[0];
Check(GeoTracking.At(geoRoute,-1).Status=="Scheduled"&&GeoTracking.At(geoRoute,-1).Progress==0,"geo predeparture");
Check(GeoTracking.At(geoRoute,0).Position==geoRoute.Hubs[0].Position,"geo departure position");
Check(GeoTracking.At(geoRoute,300).Position==geoRoute.Hubs[^1].Position&&GeoTracking.At(geoRoute,300).Status=="Arrived","geo destination position");
Check(Math.Abs(GeoTracking.At(geoRoute,150).DistanceKm-GeoTracking.Length(geoRoute)/2)<1e-8,"geo distance progression");
Check(GeoTracking.Events(geoRoutes,0).Count==1,"geo departure zone event");
Check(GeoTracking.Events(geoRoutes,720).Any(e=>e.Plate=="GEO-101"&&e.Hub=="Vienna"&&e.Kind=="Enter"),"geo destination zone entry");
Check(GeoTracking.Events(geoRoutes,720).SequenceEqual(GeoTracking.Events(geoRoutes,720)),"geo deterministic replay");
var manifestJson="""{"schemaVersion":1,"synthetic":true,"runId":"test-run-001","createdUtc":"2026-11-25T20:00:00Z","seed":42,"sourceRevision":"fixture","mlNetVersion":"5.0.0","maintenance":{"testRows":10,"testSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","reloadVerified":true,"logistic":{"TP":3,"FP":1,"TN":4,"FN":2,"F1":0.667,"Brier":0.12},"fastTree":{"TP":3,"FP":2,"TN":3,"FN":2,"F1":0.6,"Brier":0.13},"artifact":{"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}},"eta":{"testRows":10,"testSha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","reloadVerified":true,"linear":{"Mae":8,"Rmse":10},"fastTree":{"Mae":12,"Rmse":15},"artifact":{"sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}}}""";
var registry=RegistryManifest.Parse(manifestJson);
Check(registry.Seed==42&&registry.LogisticF1==.667,"registry parses manifest metrics");
Check(RegistryManifest.Comparable(registry,registry with{RunId="other"}),"registry same dataset comparison");
Check(!RegistryManifest.Comparable(registry,registry with{EtaTestHash=new string('c',64)}),"registry distinct dataset warning");
bool RejectManifest(string json){try{RegistryManifest.Parse(json);return false;}catch(FormatException){return true;}}
Check(RejectManifest(manifestJson.Replace("\"synthetic\":true","\"synthetic\":false")),"registry rejects non-synthetic manifest");
Check(RejectManifest(manifestJson.Replace("\"TP\":3","\"TP\":4")),"registry rejects invalid confusion counts");
Check(RejectManifest(manifestJson.Replace("\"F1\":0.667","\"F1\":1.5")),"registry rejects invalid metric");
Check(RejectManifest(new string('x',70000)),"registry size limit");
Check(RejectManifest("{}"),"registry incomplete manifest");
var manifestNode=System.Text.Json.Nodes.JsonNode.Parse(manifestJson)!;
var importanceNode=new System.Text.Json.Nodes.JsonObject{
    ["metric"]="Brier",["repeats"]=3,
    ["features"]=new System.Text.Json.Nodes.JsonArray(LogisticMaintenanceModel.FeatureNames.Select(name=>(System.Text.Json.Nodes.JsonNode)new System.Text.Json.Nodes.JsonObject{["feature"]=name,["meanLossIncrease"]=0.02,["minLossIncrease"]=-0.01,["maxLossIncrease"]=0.04}).ToArray())
};
manifestNode["maintenance"]!["permutationImportance"]=importanceNode;
Check(RegistryManifest.Parse(manifestNode.ToJsonString()).MaintenanceImportance?.Count==5,"registry parses optional importance");
importanceNode["features"]![0]!["meanLossIncrease"]=2;
Check(RejectManifest(manifestNode.ToJsonString()),"registry rejects out-of-range importance");
var csv=TelemetryCsv.Header+"\n1,0,84,2.1,13.6,0.3,1200,0\n1,0,85,2.2,13.5,0.31,1207,0\n2,0,105,4.2,12.2,0.95,4800,1\n3,0,NaN,2.8,13.2,0.5,2400,0\n4,0,90,2.8,13.2,0.5,2400,2\n";
var inspection=TelemetryCsv.Inspect(csv);
Check(inspection.Rows==5&&inspection.ValidRows==2&&inspection.InvalidRows==3,"CSV exact row accounting");
Check(inspection.VehicleCount==2&&inspection.PositiveLabels==1,"CSV labels and vehicle counts");
Check(inspection.Issues.Any(i=>i.Line==3&&i.Reason.Contains("Duplicate")),"CSV duplicate detection");
Check(inspection.Issues.Any(i=>i.Line==5&&i.Reason.Contains("non-finite")),"CSV nonfinite rejection");
Check(inspection.Issues.Any(i=>i.Line==6&&i.Reason.Contains("Label")),"CSV invalid label");
Check(TelemetryCsv.Inspect("\uFEFF"+TelemetryCsv.Header+"\r\n").Rows==0,"CSV BOM and empty dataset");
bool RejectCsv(string value){try{TelemetryCsv.Inspect(value);return false;}catch(FormatException){return true;}}
Check(RejectCsv("wrong_header\n"),"CSV schema rejection");
Check(RejectCsv(new string('x',TelemetryCsv.MaxBytes+1)),"CSV byte bound");
Check(RejectCsv(TelemetryCsv.Header+"\n"+string.Concat(Enumerable.Repeat("1,0,84,2.1,13.6,0.3,1200,0\n",10001))),"CSV row bound");
bool RejectImported(string value){try{MaintenanceLearning.TrainImported(value);return false;}catch(FormatException){return true;}}
