var driftReference=MaintenanceLearning.Generate(42,0,40,60).Select(r=>r.Features).ToArray();
var driftCurrent=MaintenanceLearning.Generate(42^0x5A17,1000,12,60).Select(r=>r.Features).ToArray();
var driftModel=MaintenanceLearning.Train(42).Model;
var sameDrift=ModelDrift.Compare(driftReference,driftReference,driftModel);
Check(sameDrift.Features.All(f=>f.Psi==0),"identical drift windows");
var controlDrift=ModelDrift.Compare(driftReference,driftCurrent,driftModel);
var shiftedDrift=ModelDrift.Compare(driftReference,driftCurrent.Select(x=>ModelDrift.Shift(x,1)).ToArray(),driftModel);
Check(shiftedDrift.Features[0].Psi>controlDrift.Features[0].Psi,"temperature shift detected");
Check(shiftedDrift.Features[1].Psi>controlDrift.Features[1].Psi,"vibration shift detected");
Check(shiftedDrift.Features[3].Psi==controlDrift.Features[3].Psi,"unmodified feature drift unchanged");
Check(shiftedDrift.Features.All(f=>double.IsFinite(f.Psi)&&f.Psi>=0),"finite PSI");
Check(shiftedDrift.CurrentMeanRisk>controlDrift.CurrentMeanRisk,"synthetic shifted risk");
Check(ModelDrift.Shift(driftCurrent[0],0)==driftCurrent[0],"zero shift");
var constantDrift=ModelDrift.Compare(Enumerable.Repeat(driftCurrent[0],20).ToArray(),Enumerable.Repeat(ModelDrift.Shift(driftCurrent[0],1),20).ToArray(),driftModel);
Check(constantDrift.Features.All(f=>double.IsFinite(f.Psi)),"constant feature bins");
